\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}
\usepackage{amsmath}

\title{Adjuvant Therapy and Recurrence Risk in Stage II Colon Cancer: A Multicentre Cohort Study}
\author{L.~Marchetti, K.~Okafor, and S.~Lindqvist}
\date{March 2026}

\begin{document}
\maketitle

\begin{abstract}
Adjuvant chemotherapy after resection of stage II colon cancer remains
selectively used. We analysed a multicentre cohort to estimate the
association between adjuvant therapy and recurrence risk overall.
\end{abstract}

\input{chapters/methods}
\input{chapters/results}

\section{Discussion}
The overall association was modest, and heterogeneity across clinical
subgroups warrants careful interpretation.

\end{document}

\section{Methods}
\subsection{Cohort}
We identified 2{,}184 patients who underwent curative resection for
stage II colon cancer between 2015 and 2022 at six centres.
Patients with neoadjuvant therapy or hereditary syndromes were excluded.

\subsection{Outcomes and Follow-up}
The primary endpoint was recurrence-free survival, measured from the
date of resection to recurrence or death.
Follow-up used structured chart review and registry linkage,
with a median follow-up of 5.1 years.

\subsection{Analysis}
Hazard ratios were estimated with Cox models adjusted for age, sex,
T stage, lymph node yield, and lymphovascular invasion.

\section{Results}
\subsection{Overall Association}
Adjuvant therapy was administered to 612 of 2{,}184 patients (28.0\%).
The adjusted hazard ratio for recurrence was 0.81 (95\% CI 0.63--1.04)
comparing treated with untreated patients.

\subsection{Prespecified Subgroups}
Subgroup analyses were prespecified for age and sex,
because treatment benefit is biologically plausible to vary
with comorbidity burden and tolerance.

